import { PYQQuestion } from "./previousYearPapers";

/**
 * TGPSC Agricultural Extension Officer Exam 2017
 * Pattern: Part-A General Studies (30 Qs) + Part-B Agriculture (70 Qs)
 * Duration: 150 minutes | Total: 100 Questions
 */
export const AEO_2017: PYQQuestion[] = [

  // ══ PART A: GENERAL STUDIES & TELANGANA (30 Questions) ══

  // Telangana History, Culture & Geography
  { id:"aeo17_001", year:2017, subject:"general-studies", question:"The Telangana Rashtra Samiti (TRS) was founded in:", options: ["2014", "2004", "1990", "2001"], correct: 3, explanation:"TRS (Telangana Rashtra Samiti) was founded on 27 April 2001 by K. Chandrashekar Rao (KCR). It was formed specifically to fight for a separate Telangana state and led the agitation that resulted in Telangana's formation in 2014." },
  { id:"aeo17_002", year:2017, subject:"general-studies", question:"Warangal fort was built by which Kakatiya ruler?", options: ["Ganapati Deva", "Betaraja I", "Prataparudra II", "Rudrama Devi"], correct: 0, explanation:"The Warangal fort (Orugallu Kota) with its famous stone gateways (Swayambhuvashivam) was built primarily under Ganapati Deva (1199–1262 AD), the powerful Kakatiya ruler who also built the Ramappa Temple (UNESCO World Heritage Site)." },
  { id:"aeo17_003", year:2017, subject:"general-studies", question:"'Ramappa Temple' in Telangana was recently declared as:", options: ["National Park", "UNESCO World Heritage Site", "Botanical Garden", "State Protected Monument"], correct: 1, explanation:"Ramappa Temple (Ramalingeswara temple) at Palampet, Mulugu district, built in 1213 CE under Kakatiya general Recharla Rudra, was inscribed as a UNESCO World Heritage Site in July 2021. It is the only temple named after its sculptor (Ramappa)." },
  { id:"aeo17_004", year:2017, subject:"general-studies", question:"Telangana's official language is:", options: ["Hindi", "Urdu", "Both Telugu and Urdu", "Telugu"], correct: 2, explanation:"Telangana has two official languages: Telugu (primary official language) and Urdu. Urdu has co-official status given Hyderabad's historical Nizam-era heritage and the significant Urdu-speaking population." },
  { id:"aeo17_005", year:2017, subject:"general-studies", question:"The Hyderabad Liberation Day (Telangana Formation in 1948) is observed on:", options: ["15 August", "1 November", "2 June", "17 September"], correct: 3, explanation:"17 September is observed as Hyderabad Liberation Day (also called Hyderabad Merger Day) marking the integration of Hyderabad state into India through Police Action/Operation Polo in 1948. It is a public holiday in Telangana." },
  { id:"aeo17_006", year:2017, subject:"general-studies", question:"Srisailam Wildlife Sanctuary forms part of which Tiger Reserve?", options: ["Nagarjunasagar", "Amrabad Tiger Reserve", "Papikonda Tiger Reserve", "Kawal Tiger Reserve"], correct: 0, explanation:"Srisailam Wildlife Sanctuary is part of the larger Nagarjunasagar-Srisailam Tiger Reserve (India's largest tiger reserve spanning 3,728 sq km across Telangana and AP). However, Amrabad TR was carved out of this in 2014 as Telangana's separate tiger reserve." },
  { id:"aeo17_007", year:2017, subject:"general-studies", question:"Pochampally Ikat is a GI (Geographical Indication) product of:", options: ["Warangal district", "Adilabad district", "Karimnagar district", "Nalgonda district"], correct: 3, explanation:"Pochampally Ikat sarees/fabric got GI tag — Bhoodan Pochampally is in Nalgonda district (though now administratively part of the merged Yadadri Bhuvanagiri district). The weavers use the tie-and-dye 'Ikat' technique for distinctive patterns." },
  { id:"aeo17_008", year:2017, subject:"general-studies", question:"Which district of Telangana is known as 'Rice Bowl of Telangana'?", options: ["Karimnagar", "Warangal", "Khammam", "Nalgonda"], correct: 0, explanation:"Karimnagar district (and its split districts Rajanna Sircilla, Jagtial, Peddapalli) is known as the 'Rice Bowl of Telangana' due to its extensive paddy cultivation under the Sriram Sagar (Nizamsagar) and Sriramsagar Project canals." },
  { id:"aeo17_009", year:2017, subject:"general-studies", question:"'Singareni Collieries' (SCCL), Telangana's major coal mining company, is a joint venture between:", options: ["Central Govt. only", "International mining companies", "Telangana State Government and Central Government (51:49)", "Private sector only"], correct: 2, explanation:"SCCL (Singareni Collieries Company Limited) is jointly owned by Telangana State Government (51%) and Government of India/BHC (49%). It operates the largest coalfield in South India, mainly in Godavari and Pranahita-Chevella coalfields." },
  { id:"aeo17_010", year:2017, subject:"general-studies", question:"The 'Telangana State Development Planning Society' (TSDPS) is engaged in:", options: ["Agricultural research", "Geospatial data management, GIS mapping, and planning support for Telangana", "Tourism development", "Industrial promotion"], correct: 1, explanation:"TSDPS (Telangana State Development Planning Society) is the nodal agency for geospatial technology, GIS-based planning, real-time data analytics (T-HIMS, Dharani land records), and development planning for Telangana." },

  // Indian Polity, Economy & Current Affairs
  { id:"aeo17_011", year:2017, subject:"general-studies", question:"'Goods and Services Tax' (GST) was implemented in India from:", options: ["1 April 2017", "1 January 2018", "1 July 2017", "26 January 2017"], correct: 2, explanation:"GST (Goods and Services Tax) — India's comprehensive indirect tax reform — was implemented from 1 July 2017, replacing multiple central and state taxes (excise, service tax, VAT, etc.) with a unified tax system. It was passed by Parliament in August 2016." },
  { id:"aeo17_012", year:2017, subject:"general-studies", question:"'Demonetisation' of ₹500 and ₹1000 notes in India was announced on:", options: ["15 August 2016", "1 January 2017", "8 November 2016", "2 October 2016"], correct: 2, explanation:"PM Narendra Modi announced demonetisation (withdrawal of legal tender status) of ₹500 and ₹1000 notes on 8 November 2016 (at 8 PM) with the objective of combating black money, counterfeit notes, and corruption." },
  { id:"aeo17_013", year:2017, subject:"general-studies", question:"The Right to Information (RTI) Act was enacted in:", options: ["2000", "2007", "2003", "2005"], correct: 3, explanation:"The Right to Information Act was enacted by Parliament on 15 June 2005 and came into effect on 12 October 2005. It provides citizens the right to access information from public authorities, promoting transparency and accountability." },
  { id:"aeo17_014", year:2017, subject:"general-studies", question:"Under MGNREGA, if work is not provided within 15 days of application, the state must pay:", options: ["Free food grain", "Unemployment allowance", "Double wages", "No payment — wait for work"], correct: 1, explanation:"MGNREGA mandates that if employment is not provided within 15 days of application, the state must pay unemployment allowance (1/4 wage rate for first 30 days, 1/2 wage rate thereafter) to the applicant household." },
  { id:"aeo17_015", year:2017, subject:"general-studies", question:"Which state became the first to achieve 100% household electrification under the Saubhagya scheme?", options: ["Himachal Pradesh", "Telangana", "Chhattisgarh", "Gujarat"], correct: 1, explanation:"Telangana was the first state in India to achieve 100% household electrification. Through 'Haritha Haram' and other schemes, Telangana provided 24-hour reliable power supply to both agricultural and domestic consumers." },
  { id:"aeo17_016", year:2017, subject:"general-studies", question:"'Pradhan Mantri Ujjwala Yojana' (PMUY) was launched to provide free LPG connections to:", options: ["Women from BPL (Below Poverty Line) households", "Only SC/ST families", "All rural families", "All BPL women above poverty line"], correct: 0, explanation:"PMUY (launched May 2016) provides free LPG cooking gas connections to women belonging to BPL households. Target: 8 crore connections. It aims to replace unhealthy cooking fuel (firewood, dung cakes) and reduce indoor air pollution." },

  // Science & Technology
  { id:"aeo17_017", year:2017, subject:"general-studies", question:"'Mission Indradhanush' is related to:", options: ["Space mission", "Irrigation project", "Universal immunisation of children and pregnant women against 12 vaccine-preventable diseases", "Rural electrification"], correct: 2, explanation:"Mission Indradhanush (launched December 2014) aims to immunise all unvaccinated/partially vaccinated children (0–2 years) and pregnant women against 12 vaccine-preventable diseases (polio, measles, TB, hepatitis B, etc.). Named after the 7-colour rainbow." },
  { id:"aeo17_018", year:2017, subject:"general-studies", question:"'Aadhaar' biometric identity programme is governed by which Act?", options: ["National Security Act", "Aadhaar (Targeted Delivery of Financial and Other Subsidies, Benefits and Services) Act 2016", "The Constitution", "Information Technology Act"], correct: 1, explanation:"Aadhaar Act 2016 provides the legal framework for UIDAI (Unique Identification Authority of India) to collect biometric data, issue 12-digit Aadhaar numbers, and link Aadhaar to welfare schemes for targeted delivery of benefits." },
  { id:"aeo17_019", year:2017, subject:"general-studies", question:"ISRO successfully launched 104 satellites in a single mission (PSLV-C37) in:", options: ["2015", "2018", "2017", "2016"], correct: 2, explanation:"On 15 February 2017, ISRO launched 104 satellites simultaneously using PSLV-C37, setting a world record for most satellites launched in a single rocket. This included India's Cartosat-2D and 101 international nano-satellites." },
  { id:"aeo17_020", year:2017, subject:"general-studies", question:"'Direct Benefit Transfer' (DBT) in India aims to:", options: ["Transfer subsidies/benefits directly to beneficiaries' bank accounts, eliminating middlemen", "Promote exports", "Reduce agricultural production", "Increase government spending"], correct: 0, explanation:"DBT transfers government subsidies and welfare scheme payments (fertilizer subsidy, scholarships, MGNREGA wages, PM-KISAN, LPG subsidy) directly to beneficiaries' Aadhaar-linked bank accounts, reducing leakage and ensuring targeted delivery." },

  // Aptitude & Reasoning
  { id:"aeo17_021", year:2017, subject:"general-studies", question:"A field is 200m × 150m. If fencing costs ₹15 per metre, what is the total cost of fencing the field?", options: ["₹67,500", "₹10,500", "₹52,500", "₹30,000"], correct: 1, explanation:"Wait - this needs recalculation. Perimeter = 2(200+150) = 2×350 = 700m. Total cost = 700 × 15 = ₹10,500. Answer: ₹10,500.", explanation:"Perimeter = 2×(200+150) = 700m. Cost = 700 × ₹15 = ₹10,500." },
  { id:"aeo17_022", year:2017, subject:"general-studies", question:"If a farmer sells 40 kg of paddy at ₹1,410 per quintal, what amount does he receive?", options: ["₹56.40", "₹564", "₹56,400", "₹5,640"], correct: 1, explanation:"1 quintal = 100 kg. 40 kg = 0.4 quintal. Amount = 0.4 × 1410 = ₹564. The farmer receives ₹564 for 40 kg of paddy at MSP rate." },
  { id:"aeo17_023", year:2017, subject:"general-studies", question:"In a village, 60% of households have a radio and 40% have a TV. 25% have both. What % have neither?", options: ["35%", "25%", "15%", "20%"], correct: 1, explanation:"Using set theory: P(Radio∪TV) = 60+40-25 = 75%. P(neither) = 100-75 = 25%. So 25% of households have neither radio nor TV." },
  { id:"aeo17_024", year:2017, subject:"general-studies", question:"If today is Wednesday, what day will it be 100 days from now?", options: ["Wednesday", "Friday", "Monday", "Tuesday"], correct: 1, explanation:"100 ÷ 7 = 14 weeks + 2 days. Wednesday + 2 days = Friday. So 100 days from Wednesday is Friday." },
  { id:"aeo17_025", year:2017, subject:"general-studies", question:"Which word does NOT belong: Kharif, Rabi, Zaid, Annual?", options: ["Zaid", "Rabi", "Kharif", "Annual"], correct: 3, explanation:"Kharif, Rabi, and Zaid are crop seasons in India (Kharif=rainy, Rabi=winter, Zaid=summer). 'Annual' refers to plant life cycle (completes in one year), not a cropping season — it is the odd one out." },

  // Telangana Current Affairs 2016-17
  { id:"aeo17_026", year:2017, subject:"general-studies", question:"Which project was launched in Telangana for integrated rural development named after a Kakatiya queen?", options: ["Rythu Bandhu", "Indira Prabha", "Mission Kakatiya", "Mission Bhagiratha"], correct: 2, explanation:"Mission Kakatiya (launched March 2015) aims to restore the historical irrigation tank network of Telangana, inspired by the Kakatiya dynasty's sophisticated water management. Target: restoration of 46,531 tanks across Telangana." },
  { id:"aeo17_027", year:2017, subject:"general-studies", question:"'Haritha Haram' programme in Telangana aims to achieve what percentage forest and tree cover?", options: ["24%", "40%", "33%", "50%"], correct: 3, explanation:"Haritha Haram (Green Garland) programme launched in 2015 aims to increase Telangana's tree cover from the current 24% to 33% initially (as per National Forest Policy) and ultimately to 50% of geographic area — planting 230 crore saplings." },
  { id:"aeo17_028", year:2017, subject:"general-studies", question:"The Kaleshwaram Lift Irrigation Scheme (KLIS) was approved to irrigate how many acres?", options: ["37 lakh acres", "18.25 lakh acres", "50 lakh acres", "5 lakh acres"], correct: 0, explanation:"Kaleshwaram Lift Irrigation Scheme is designed to irrigate 18.25 lakh acres (in Phase-I). However, the broader KLIS vision covers 37 lakh acres and provides drinking water to Hyderabad and other towns. It is the world's largest multi-stage lift irrigation project." },
  { id:"aeo17_029", year:2017, subject:"general-studies", question:"'TS-iPASS' (Telangana State Industrial Project Approval and Self Certification System) was implemented to:", options: ["Control pollution", "Improve agricultural marketing", "Manage land records", "Streamline industrial approvals within 15 days for new investment and employment generation"], correct: 3, explanation:"TS-iPASS is an online single-window system for industrial approvals in Telangana. It approves all clearances (permissions, licences) for new industrial investments within 15 days, making Telangana one of the most investor-friendly states." },
  { id:"aeo17_030", year:2017, subject:"general-studies", question:"Telangana's total number of districts after reorganisation in 2016 is:", options: ["10", "33", "23", "31"], correct: 1, explanation:"On 11 October 2016, Telangana was reorganised from 10 districts to 31 districts (later expanded to 33). The reorganisation was done to bring administration closer to people and implement government schemes more effectively." },

  // ══ PART B: AGRICULTURE (70 Questions) ══

  // Agricultural Extension (15 Qs)
  { id:"aeo17_031", year:2017, subject:"extension", question:"'Kisan Mela' is an example of which type of extension method?", options: ["Mass contact method", "Group method", "None", "Individual method"], correct: 1, explanation:"Kisan Mela (Farmers' Fair) is a group extension method that brings together large groups (50–500 farmers) for demonstrations, exhibitions, competitions, and interaction with scientists. It is more than a group meeting but less than mass media." },
  { id:"aeo17_032", year:2017, subject:"extension", question:"The main purpose of 'result demonstration' in extension education is to:", options: ["Train extension workers", "Show HOW to do something", "Sell agricultural inputs", "Show WHAT results can be obtained by adopting a recommended practice"], correct: 3, explanation:"Result demonstration shows farmers WHAT results (yield, profit, quality) can be obtained by adopting a recommended technology on their own or a neighbouring farm. It motivates adoption by showing proof of benefit in local conditions." },
  { id:"aeo17_033", year:2017, subject:"extension", question:"Under which scheme are Soil Health Cards prepared and distributed to farmers?", options: ["RKVY", "National Food Security Mission", "PM-KISAN", "Soil Health Card Scheme (under NMSA)"], correct: 3, explanation:"Soil Health Cards are issued under the Soil Health Card Scheme, a sub-scheme of NMSA (National Mission for Sustainable Agriculture). Cards are issued every 2 years based on soil testing, providing crop-wise nutrient recommendations." },
  { id:"aeo17_034", year:2017, subject:"extension", question:"'Farmer Producer Organisation' (FPO) is essentially a:", options: ["NGO funded by foreign aid", "Private company with shareholder farmers having no voting rights", "Government agricultural department", "Collective business enterprise owned by farmers for better input access, production, and marketing"], correct: 3, explanation:"FPO is a type of Producer Company (registered under Companies Act 2013) owned and managed by farmers. Members share profits, access quality inputs at reduced cost, and collectively market produce at better prices." },
  { id:"aeo17_035", year:2017, subject:"extension", question:"'Agri-Clinics and Agri-Business Centres' scheme is implemented by:", options: ["Ministry of Finance", "ICAR", "NABARD with MANAGE to promote agri-entrepreneurship", "Reserve Bank of India"], correct: 2, explanation:"Agri-Clinics & Agri-Business Centres (ACABC) scheme is implemented jointly by NABARD (credit) and MANAGE (training) to encourage agriculture graduates to set up agri-ventures (input shops, diagnostic labs, soil testing) as entrepreneurs." },
  { id:"aeo17_036", year:2017, subject:"extension", question:"'Gram Panchayat Agriculture Plan' (GPAP) is prepared by:", options: ["Village", "State Agriculture Department alone", "KVK scientists", "District Collector's office"], correct: 0, explanation:"GPAP (Gram Panchayat Agriculture Plan) is a decentralised planning exercise where farmers, Gram Panchayat members, extension workers, and line department officers jointly prepare an agriculture development plan for each village/GP." },
  { id:"aeo17_037", year:2017, subject:"extension", question:"'Zero-based budgeting' in extension programme planning means:", options: ["Using only government funds", "Planning based on previous year's budget", "Each planning cycle starts fresh without assuming continuation of past activities — justifying every expenditure", "Planning without any budget"], correct: 2, explanation:"Zero-based budgeting (ZBB) requires every expense in a programme to be justified for each budget cycle, starting from 'zero' base. Unlike incremental budgeting (building on previous budget), ZBB prevents continuation of ineffective activities." },
  { id:"aeo17_038", year:2017, subject:"extension", question:"'IFFCO Kisan' app provides what service to farmers?", options: ["Agri", "Only soil testing request", "Only fertilizer ordering", "Only government scheme information"], correct: 0, explanation:"IFFCO Kisan app provides comprehensive agricultural services: crop advisory, weather forecast, market prices, soil health information, government schemes, video tutorials in multiple regional languages, targeting 7 crore+ farmer users." },
  { id:"aeo17_039", year:2017, subject:"extension", question:"'Technology backstopping' in KVK means:", options: ["KVK selling seeds and fertilizers", "KVK providing technical support, guidance, and on-call advisory to extension workers in the district", "KVK funding farmers directly", "KVK managing irrigation projects"], correct: 1, explanation:"Technology backstopping is a core function of KVKs: providing technical guidance, troubleshooting, reference material, and on-demand advisory to extension workers (AAOs, AOs) when they encounter technical problems beyond their competence." },
  { id:"aeo17_040", year:2017, subject:"extension", question:"The 'Revised Yellow Revolution' initiative is related to:", options: ["Edible oilseeds production", "Paddy production", "Horticulture development", "Fisheries development"], correct: 0, explanation:"Yellow Revolution refers to the development of oilseed production in India. The revised/second yellow revolution aims to increase domestic oilseed production (groundnut, mustard, sunflower, soybean) to reduce India's large import bill for edible oils." },
  { id:"aeo17_041", year:2017, subject:"extension", question:"Which of the following is a National Level Farmers Award?", options: ["Padma Shri only", "Dronacharya Award", "Arjuna Award", "Krishi Karman Award (for states) and Pandit Deen Dayal Upadhyay Puraskar (for farmers)"], correct: 3, explanation:"National level agricultural awards include: Krishi Karman Award (for states achieving best food grain production) and various farmer-level awards including Pandit Deen Dayal Upadhyay Krishi Vigyan Protsahan Puraskar for outstanding farmer achievement." },
  { id:"aeo17_042", year:2017, subject:"extension", question:"'Social audit' in MGNREGA requires that all works and expenditure records be:", options: ["Kept confidential", "Available only to government auditors", "Maintained only at district headquarters", "Publicly displayed at Gram Panchayat and verified at Gram Sabha meetings"], correct: 3, explanation:"MGNREGA mandates periodic social audits where all work details, wages paid, and expenditure records are publicly displayed at Gram Panchayat level and read out at Gram Sabha for community verification — empowering citizens as watchdogs." },
  { id:"aeo17_043", year:2017, subject:"extension", question:"'Rythu Vedika' centres in Telangana are established at:", options: ["District collector's office", "Village level only", "Mandal level for providing agricultural information, weather data, and advisory services to farmers", "State headquarters only"], correct: 2, explanation:"Rythu Vedika (Farmer Forum) centres at mandal level serve as information and service delivery hubs for farmers — providing weather information, market prices, advisory services, scheme information, and facilitating interaction with agriculture department officials." },
  { id:"aeo17_044", year:2017, subject:"extension", question:"Under 'PM Fasal Bima Yojana', the premium rate for kharif crops is:", options: ["1% of sum insured", "10% of sum insured", "2% of sum insured (or actuarial rate, whichever is less) for notified crops", "5% of sum insured"], correct: 2, explanation:"PMFBY premium rates: 2% (or actuarial rate if lower) for Kharif crops, 1.5% for Rabi crops, 5% for annual commercial/horticultural crops. Premium above these rates is shared equally between Central and State governments." },
  { id:"aeo17_045", year:2017, subject:"extension", question:"The 'National Agricultural Market' (e-NAM) was designed to:", options: ["Import agricultural produce", "Create an online unified national market linking existing APMCs for transparent price discovery", "Replace APMCs entirely", "Establish government-owned shops"], correct: 1, explanation:"e-NAM does NOT replace APMCs — it creates an online trading layer connecting existing APMC mandis. Farmers, traders, and buyers can trade on the platform using transparent e-bidding, reducing market fragmentation and improving price realisation." },

  // Agronomy (15 Qs)
  { id:"aeo17_046", year:2017, subject:"agronomy", question:"Which nutrient deficiency causes 'Khaira disease' in paddy?", options: ["Iron", "Manganese", "Nitrogen", "Zinc"], correct: 3, explanation:"Khaira disease of paddy is caused by Zinc (Zn) deficiency. Symptoms appear 2–4 weeks after transplanting: pale yellow-brown spots on leaves, stunting, delayed tillering, and poor root development. Managed by ZnSO4 application." },
  { id:"aeo17_047", year:2017, subject:"agronomy", question:"'Herbicide resistance' in weeds is best managed by:", options: ["Stopping herbicide use entirely", "Rotating herbicide modes of action, using mixtures, and integrating non-chemical methods", "Using more herbicide", "Using the same herbicide at higher doses"], correct: 1, explanation:"Herbicide resistance management: rotate herbicide modes of action (different sites of action), use tank mixes of herbicides with different modes of action, integrate mechanical/cultural methods (crop rotation, hand weeding) to reduce selection pressure." },
  { id:"aeo17_048", year:2017, subject:"agronomy", question:"'Aerobic rice cultivation' is suitable for:", options: ["Terraced hill slopes only", "Low-lying waterlogged areas", "Coastal saline areas", "Well"], correct: 3, explanation:"Aerobic rice is grown in non-puddled, non-flooded, well-drained soils (like upland crops) using varieties adapted to aerobic conditions (DSR-1, MAS 946-1). It saves 40–55% water compared to flooded rice with 20–30% yield reduction." },
  { id:"aeo17_049", year:2017, subject:"agronomy", question:"'Ratoon cropping' in sugarcane involves:", options: ["Planting fresh setts every year", "Grafting sugarcane varieties", "Transplanting sugarcane", "Allowing new shoots to emerge from stubble after harvest for a second crop"], correct: 3, explanation:"Ratoon cropping in sugarcane harvests a second (and sometimes third) crop from shoots (ratoon/stubble shoots) that emerge from the stump left after harvesting the plant crop. Ratoon cane saves 20–25% input costs." },
  { id:"aeo17_050", year:2017, subject:"agronomy", question:"Telangana's cotton is mostly grown in which districts?", options: ["Southern Telangana only", "Only Hyderabad", "Adilabad, Komuram Bheem, and Nirmal districts", "Karimnagar and Warangal (paddy districts)"], correct: 2, explanation:"Cotton is predominantly grown in northern Telangana — Adilabad, Komuram Bheem, Mancherial, Nirmal, Nizamabad, and Jagityal districts. These areas have black cotton soils (Vertisols) and receive adequate rainfall for cotton cultivation." },
  { id:"aeo17_051", year:2017, subject:"agronomy", question:"What is the recommended N:P₂O₅:K₂O fertilizer dose for high-yielding paddy in Telangana (kg/ha)?", options: ["80:40:40", "150:75:75", "40:20:0", "120:60:40"], correct: 3, explanation:"Recommended NPK dose for high-yielding paddy in Telangana: 120 kg N : 60 kg P₂O₅ : 40 kg K₂O per hectare (for districts with good K status). This is applied in 3 splits for N (basal, AT, PI) and basal for P and K." },
  { id:"aeo17_052", year:2017, subject:"agronomy", question:"'Transplanted rice' compared to direct seeded rice has the advantage of:", options: ["Lower labour cost", "Higher seed requirement", "Lower water requirement", "Better weed control due to anaerobic conditions after transplanting"], correct: 3, explanation:"Transplanted rice creates anaerobic (flooded) conditions after transplanting, suppressing germination of most annual weeds. This gives a significant advantage in weed management compared to dry-seeded direct sown rice." },
  { id:"aeo17_053", year:2017, subject:"agronomy", question:"'Mulching' in vegetable cultivation helps in:", options: ["Promoting soil erosion", "Increasing evaporation", "Increasing soil compaction", "Conserving soil moisture, regulating soil temperature, and suppressing weeds"], correct: 3, explanation:"Mulching (covering soil with organic or plastic materials) conserves soil moisture by reducing evaporation, moderates extreme soil temperatures, suppresses weed germination, prevents soil splash erosion, and (organic mulch) adds organic matter." },
  { id:"aeo17_054", year:2017, subject:"agronomy", question:"National Average of paddy yield in India is approximately:", options: ["4.5 t/ha", "1.5 t/ha", "2.0 t/ha", "2.6 t/ha"], correct: 3, explanation:"India's national average paddy yield is approximately 2.6 t/ha (2,600 kg/ha). Punjab achieves ~4.5 t/ha (highest) while Telangana averages ~2.8–3.0 t/ha. Global average is ~4.7 t/ha. Potential yield with best varieties is 8–10 t/ha." },
  { id:"aeo17_055", year:2017, subject:"agronomy", question:"'HADP' (High Altitude Dry Plateaus) farming problems in Telangana include:", options: ["Excess rainfall and flooding", "Frost damage", "Drought, shallow red soils, low organic matter, and rainfed conditions", "Salinity and waterlogging"], correct: 2, explanation:"High altitude dry plateau areas (northern and eastern Telangana) face: erratic and low rainfall (<750mm), shallow red soils with low water holding capacity and organic matter, predominantly rainfed conditions, and high crop risk." },
  { id:"aeo17_056", year:2017, subject:"agronomy", question:"'Fertigation' refers to:", options: ["Irrigation water quality testing", "Application of water", "Applying fertilizer in furrows manually", "Foliar fertilizer spraying"], correct: 1, explanation:"Fertigation is the technique of applying fertilizers dissolved in water through the irrigation system (drip or sprinkler). It delivers nutrients directly to the root zone, improving fertilizer use efficiency by 20–30% compared to soil application." },
  { id:"aeo17_057", year:2017, subject:"agronomy", question:"Which crop is grown as a 'trap crop' for Spodoptera (fall armyworm/leaf armyworm) in cotton?", options: ["Maize", "Paddy", "Castor", "Soybean"], correct: 0, explanation:"Maize planted as a border trap crop around cotton attracts Spodoptera litura (cotton/maize leaf armyworm) away from cotton. When pest population builds up on maize trap rows, targeted pesticide can be applied only on trap rows." },
  { id:"aeo17_058", year:2017, subject:"agronomy", question:"'Crop diversification' in Telangana context means shifting from:", options: ["Reducing total crop area", "Traditional food crops only", "Importing crops instead of growing", "Paddy mono"], correct: 3, explanation:"Crop diversification in Telangana encourages farmers to shift from water-intensive paddy mono-culture to pulses (redgram, moong), oilseeds (sunflower, groundnut), vegetables, and horticulture, improving income stability and natural resource conservation." },
  { id:"aeo17_059", year:2017, subject:"agronomy", question:"'Pulses Mission' in Telangana aims to increase area under:", options: ["Only black gram", "Groundnut only", "Redgram, bengal gram, green gram, and black gram — all major pulses", "Soybean only"], correct: 2, explanation:"Pulses Mission/NHM Pulses component in Telangana promotes all four major pulses: redgram (pigeon pea, major kharif pulse), bengal gram (chickpea, rabi), green gram (moong, kharif/zaid), and black gram (urad, kharif) through HYV seeds and input support." },
  { id:"aeo17_060", year:2017, subject:"agronomy", question:"The 'FLD' (Front Line Demonstration) in crops is conducted at:", options: ["In laboratories only", "On farmers' fields using farmers' land and resources with research institute backstopping", "Research station under controlled conditions", "At government farms only"], correct: 1, explanation:"FLDs are conducted on farmers' own fields (not research stations) using the farmer's land and labour, with technical backstopping from KVK/ICAR. This demonstrates real farm-level performance of new varieties/practices in farmers' conditions." },

  // Soil Science (12 Qs)
  { id:"aeo17_061", year:2017, subject:"soil-science", question:"Telangana's dominant soil order covering about 45% of geographical area is:", options: ["Vertisols (Black cotton soils)", "Alfisols (Red soils)", "Inceptisols", "Entisols"], correct: 1, explanation:"Alfisols (Red soils — loamy and sandy loam textured, low in organic matter, well-drained) cover about 45% of Telangana's area. Vertisols (black cotton soils) cover about 30% of the area, predominantly in Nalgonda, Mahbubnagar, and Warangal regions." },
  { id:"aeo17_062", year:2017, subject:"soil-science", question:"'Soil test based recommendations' require soil sampling up to which depth for dryland crops?", options: ["0–60 cm", "0–5 cm", "0–15 cm (topsoil/plough layer)", "0–30 cm"], correct: 2, explanation:"For dryland field crops, soil samples are collected from 0–15 cm depth (plough layer) for routine nutrient analysis (N, P, K, pH, EC). For deep-rooted crops or subsoil problems, 15–30 cm is also collected." },
  { id:"aeo17_063", year:2017, subject:"soil-science", question:"'Acidic soils' are common in which regions of Telangana?", options: ["Delta areas", "Arid western Telangana", "High rainfall forest areas of Adilabad, Khammam, and Bhadradri", "Black cotton soil areas (Nalgonda, Mahbubnagar)"], correct: 2, explanation:"Acidic soils (pH < 6.0) are found in high rainfall areas of Adilabad, Asifabad, Khammam, and Bhadradri-Kothagudem where leaching is high. Lime application is recommended. Black cotton soil areas are neutral to alkaline." },
  { id:"aeo17_064", year:2017, subject:"soil-science", question:"The 'Critical Level' of available Zinc (Zn) in soil is:", options: ["0.3 mg/kg", "5 mg/kg", "0.01 mg/kg", "10 mg/kg"], correct: 0, explanation:"The critical level for Zn in soil (DTPA extraction method) is 0.3 mg/kg (Lindsay and Norvell method). Soils with DTPA-Zn below 0.3 mg/kg are likely to show crop response to zinc application. This threshold is used across India for recommendations." },
  { id:"aeo17_065", year:2017, subject:"soil-science", question:"'Nitrification inhibitor' DCD (Dicyandiamide) when coated on urea helps in:", options: ["Controlling weeds", "Slowing conversion of ammonium to nitrate, reducing N losses through leaching and denitrification", "Increasing P availability", "Improving K uptake"], correct: 1, explanation:"DCD (Dicyandiamide) and NBPT inhibit Nitrosomonas bacteria activity, slowing ammonium → nitrate conversion (nitrification). This keeps N as NH4+ (less mobile) in soil longer, reducing nitrate leaching and denitrification losses." },
  { id:"aeo17_066", year:2017, subject:"soil-science", question:"Composting of organic matter is primarily an:", options: ["Anaerobic process only", "Chemical reaction with water", "Physical breakdown only", "Aerobic microbiological decomposition process (aerobic composting is most common)"], correct: 3, explanation:"Aerobic composting (the Bangalore/hot method) involves microbial decomposition by aerobic organisms (bacteria, fungi, actinomycetes) under aerobic conditions, generating heat (55-65°C) that kills pathogens and weed seeds. Anaerobic composting also exists." },
  { id:"aeo17_067", year:2017, subject:"soil-science", question:"'Soil electrical conductivity' (EC) is used to assess:", options: ["Soil salinity", "Soil texture", "Soil organic matter content", "Soil pH"], correct: 0, explanation:"Electrical conductivity (EC) of soil saturation extract (ECe) measures total dissolved salts — primary indicator of soil salinity. ECe > 4 dS/m is saline; most crops are affected above 2–4 dS/m depending on crop sensitivity." },
  { id:"aeo17_068", year:2017, subject:"soil-science", question:"'Biofertilizers' used for phosphorus solubilisation in soil are:", options: ["Rhizobium", "PSB", "BGA", "Azotobacter"], correct: 1, explanation:"Phosphate Solubilising Bacteria (PSB) like Bacillus subtilis, Pseudomonas fluorescens, and Aspergillus niger produce organic acids and enzymes that convert insoluble soil phosphates (Ca-P, Fe-P, Al-P) to plant-available soluble forms." },
  { id:"aeo17_069", year:2017, subject:"soil-science", question:"The 'Critical Limit' of available Phosphorus (P) in soil by Olsen's method is:", options: ["2 kg/ha", "50 kg/ha", "10–12 kg/ha (21–25 kg P2O5/ha)", "100 kg/ha"], correct: 2, explanation:"Critical level for available P by Olsen's method (NaHCO3 extraction) is approximately 10–12 kg P/ha (21–25 kg P2O5/ha). Below this, crop shows response to P application; above this, additional P application gives marginal or no response." },
  { id:"aeo17_070", year:2017, subject:"soil-science", question:"'Micronutrient deficiency' in crops is effectively managed by:", options: ["Soil application and foliar spray of specific micronutrient salts (ZnSO4, FeSO4, Borax)", "Changing crop variety", "Increasing NPK doses", "Adding more organic matter only"], correct: 0, explanation:"Micronutrient deficiencies are corrected by: soil application of specific salts (ZnSO4 at 25 kg/ha, Borax at 5–10 kg/ha) and/or foliar sprays (0.5% ZnSO4, 0.1% FeSO4, 0.1% Borax). Chelated forms (EDTA-Zn, Fe-EDTA) are more effective on alkaline soils." },
  { id:"aeo17_071", year:2017, subject:"soil-science", question:"Soil Organic Carbon (SOC) in most Telangana red soils is generally:", options: ["Medium (1.5–3%)", "Low (<0.5%)", "High (>3%)", "Very High (>5%)"], correct: 1, explanation:"Telangana's red (alfisol) soils are characteristically low in organic matter (OC < 0.5%, often 0.2–0.4%) due to high temperatures accelerating decomposition, low biomass return to soil, and burning of crop residues." },
  { id:"aeo17_072", year:2017, subject:"soil-science", question:"'Carbon Sequestration' through agriculture means:", options: ["Storing atmospheric CO2 in soil organic matter through crop production practices (zero-till, cover crops, organic amendments)", "Applying more chemical fertilizers", "Burning crop residues to release CO2", "Converting agricultural land to forest"], correct: 0, explanation:"Agricultural carbon sequestration stores atmospheric CO2 as soil organic carbon (SOC) through: zero/reduced tillage (less SOC oxidation), cover cropping, organic amendments, agroforestry, and perennial crops. Each 1% increase in SOC sequesters ~15 t CO2/ha." },

  // Plant Protection (13 Qs)
  { id:"aeo17_073", year:2017, subject:"entomology", question:"'Crop monitoring' for pest management involves:", options: ["Regular scouting of fields to count pest and natural enemy populations for ETL", "Applying pesticides preventively at crop emergence", "Contacting extension officer only when severe damage occurs", "Spraying pesticides at fixed calendar intervals"], correct: 0, explanation:"Crop monitoring (pest scouting) involves systematic field visits at fixed intervals to observe pest populations, natural enemies, and crop damage. Data is compared against ETL to make economically rational, ecologically sound decisions about when/whether to spray." },
  { id:"aeo17_074", year:2017, subject:"entomology", question:"'Helicoverpa armigera' (American bollworm/gram pod borer) damages:", options: ["Only cereals", "Only pulses", "Only cotton", "Multiple crops including cotton, chickpea, tomato, sorghum, maize (highly polyphagous)"], correct: 3, explanation:"H. armigera is one of the most polyphagous pest species — attacking over 180 plant species including cotton bolls (cotton bollworm), chickpea pods (gram pod borer), tomato fruits, and many other crops, causing significant economic damage." },
  { id:"aeo17_075", year:2017, subject:"entomology", question:"The most effective management strategy for Bt-cotton resistance in pink bollworm is:", options: ["Stopping Bt cotton cultivation", "Planting non", "Using higher Bt doses", "Using more insecticide sprays"], correct: 1, explanation:"Refuge strategy (IRM — Insecticide Resistance Management) for Bt cotton: plant 20% non-Bt cotton (refuge) to maintain susceptible pink bollworm population. Mating between resistant (from Bt fields) and susceptible insects delays resistance development." },
  { id:"aeo17_076", year:2017, subject:"plant-pathology", question:"'Early blight' of potato and tomato is caused by:", options: ["Alternaria solani", "Fusarium solani", "Phytophthora infestans", "Pythium ultimum"], correct: 0, explanation:"Early blight of potato and tomato is caused by Alternaria solani. Symptoms: target-board (concentric ring) lesions on older leaves, starting as dark brown spots. Managed by Mancozeb/Chlorothalonil sprays. Distinguished from late blight (Phytophthora)." },
  { id:"aeo17_077", year:2017, subject:"entomology", question:"'Yellow sticky traps' are used for monitoring which pest in vegetable crops?", options: ["Whiteflies, aphids, and leaf miners (attracted to yellow colour)", "Root grubs", "Cutworms", "Stem borers"], correct: 0, explanation:"Yellow sticky traps (25×30 cm yellow cards coated with sticky material) are used for monitoring whiteflies, aphids, leaf miners, and thrips — all of which are attracted to the colour yellow. Trap count helps make ETL-based spray decisions." },
  { id:"aeo17_078", year:2017, subject:"plant-pathology", question:"'Anthracnose' disease in chilli and mango is caused by:", options: ["Phytophthora sp.", "Botrytis cinerea", "Fusarium sp.", "Colletotrichum gloeosporioides/C. capsici"], correct: 3, explanation:"Anthracnose of chilli (C. capsici) and mango (C. gloeosporioides) causes dark, sunken, water-soaked lesions on fruits. The pathogen infects immature fruits and the disease becomes apparent during ripening. Major post-harvest disease of both crops." },
  { id:"aeo17_079", year:2017, subject:"entomology", question:"'Biocontrol using NPV' (Nuclear Polyhedrosis Virus) is effective against:", options: ["All insect pests equally", "Lepidopteran larvae (caterpillars) — highly specific", "Soil insects", "Aphids and whiteflies"], correct: 1, explanation:"NPV (Nuclear Polyhedrosis Virus) is a baculovirus that is highly host-specific and effective against lepidopteran larvae. Helicoverpa NPV (HaNPV, at 250 LE/ha) and Spodoptera NPV are commercially produced for management of respective pests." },
  { id:"aeo17_080", year:2017, subject:"plant-pathology", question:"'Integrated Disease Management' (IDM) in rice includes:", options: ["Combination of resistant varieties, cultural practices, bio-control (Pseudomonas, Trichoderma), and judicious chemical use", "Avoiding any chemical use", "Using maximum pesticides", "Using only fungicides"], correct: 0, explanation:"IDM combines: resistant varieties (blast-resistant MTU 1010, BLB-resistant BPT 5204), cultural practices (balanced fertilization, proper spacing), biocontrol (Pseudomonas fluorescens for blast, BLB), and need-based fungicide/bactericide applications." },
  { id:"aeo17_081", year:2017, subject:"entomology", question:"'Spray schedule' based IPM for cotton recommends first spray at:", options: ["Only at boll development stage", "At seedling stage (14 DAS) against soil-borne pests", "At 45–60 DAS when ETL is reached for sucking pests", "At sowing"], correct: 2, explanation:"Cotton IPM spray calendar: avoid prophylactic sprays. First spray at 45–60 DAS only when sucking pest ETL is reached (jassid: 3/leaf, thrips: 5/leaf, whitefly: 6 adults/leaf). Early sprays destroy natural enemies that control pests naturally." },
  { id:"aeo17_082", year:2017, subject:"plant-pathology", question:"'Charcoal rot' of sorghum and soybean is caused by:", options: ["Rhizoctonia solani", "Phytophthora sojae", "Macrophomina phaseolina", "Sclerotinia sclerotiorum"], correct: 2, explanation:"Charcoal rot (dry weather disease) is caused by Macrophomina phaseolina — a soil-borne fungus that produces microsclerotia (giving the characteristic black/charcoal colour in infected tissue). It is most severe under drought and heat stress conditions." },
  { id:"aeo17_083", year:2017, subject:"entomology", question:"'Leaf curl' of chilli is caused by:", options: ["Bacterial infection", "Thrips (Scirtothrips dorsalis) — secondary to possible Chilli Leaf Curl Virus (ChiLCV)", "Nutrient deficiency", "Fungal pathogen"], correct: 1, explanation:"Chilli leaf curl complex: Thrips (Scirtothrips dorsalis, yellow thrips) cause upward curling of leaves through feeding. Some cases involve Chilli Leaf Curl Virus (ChiLCV, begomovirus) transmitted by thrips. Management: imidacloprid/spinosad for thrips." },
  { id:"aeo17_084", year:2017, subject:"plant-pathology", question:"'Bactericide' Copper Oxychloride (COC) is used at what concentration for bacterial diseases?", options: ["5% spray", "0.3% (3g/l) spray", "0.05% (0.5g/l)", "10% soil drench"], correct: 1, explanation:"Copper Oxychloride (COC/Blitox) is used as foliar spray at 0.3% (3g per litre water) or 600g/200L water/acre for managing bacterial diseases (rice BLB, citrus canker, vegetable bacterial blight) and as a protectant fungicide." },
  { id:"aeo17_085", year:2017, subject:"entomology", question:"Which of the following is a beneficial insect that should be protected while spraying insecticides?", options: ["Spodoptera litura", "Helicoverpa armigera", "Chrysoperla carnea", "Anomis flava"], correct: 2, explanation:"Chrysoperla carnea (common lacewing, green lacewing) is an important generalist predator. Both larvae and adults prey on aphids, thrips, mites, small caterpillars, and whiteflies. It is susceptible to broad-spectrum insecticides and should be protected." },

  // Horticulture (10 Qs)
  { id:"aeo17_086", year:2017, subject:"horticulture", question:"The term 'Hardening' of seedlings in vegetable nursery refers to:", options: ["Adding fertilizers to make seedlings strong", "Gradually exposing nursery seedlings to outdoor conditions before transplanting to reduce transplant shock", "Treating seeds with chemicals", "Applying growth regulators"], correct: 1, explanation:"Hardening is the process of gradually acclimatising nursery seedlings (grown under protected conditions) to outdoor/field conditions — reducing irrigation, increasing light exposure, and lowering temperature over 7–10 days before transplanting." },
  { id:"aeo17_087", year:2017, subject:"horticulture", question:"'Himayat' (Imam Pasand) mango variety is special because:", options: ["It is suitable only for processing", "It is resistant to mango hoppers", "It is the largest mango with distinctive elongated shape and very sweet flesh", "It has earliest maturity"], correct: 2, explanation:"Himayat (Imam Pasand) mango from Telangana/AP is called 'Emperor among mangoes' — known for its very large size (600–900g), elongated shape, yellow skin, fibreless flesh, and exceptional sweetness. It has a GI tag and commands premium price." },
  { id:"aeo17_088", year:2017, subject:"horticulture", question:"'Tissue culture' propagated banana planting material is superior because:", options: ["Better drought tolerance", "Higher yield guaranteed always", "Cheaper than suckers", "Disease"], correct: 3, explanation:"Tissue culture (TC) banana plants are superior to conventional suckers because: they are disease-free (free from bunchy top virus, banana mosaic), genetically uniform, have better stand establishment, earlier production, and higher yield." },
  { id:"aeo17_089", year:2017, subject:"horticulture", question:"'Drip irrigation' in chilli at Telangana Agricultural University recommendation saves water by:", options: ["10%", "60–70%", "25–30%", "40–50%"], correct: 3, explanation:"Drip irrigation in chilli saves approximately 40–50% water compared to traditional furrow irrigation while achieving the same or higher yield. It also reduces fungal disease incidence (no wet foliage), improves fertilizer use efficiency through fertigation." },
  { id:"aeo17_090", year:2017, subject:"horticulture", question:"'Cucumber Mosaic Virus' (CMV) in vegetables is transmitted by:", options: ["Whitefly — persistent manner", "Aphids — in non-persistent manner", "Beetles (contact)", "Nematodes"], correct: 1, explanation:"CMV (one of the most common plant viruses affecting over 1,200 species) is primarily transmitted by aphids (more than 80 species) in a non-persistent (stylet-borne) manner — transmitted within seconds of probing and lost quickly." },
  { id:"aeo17_091", year:2017, subject:"horticulture", question:"'Protected cultivation' (polyhouse/greenhouse) in Telangana is promoted for:", options: ["High", "Only research purposes", "Only during summer season", "All field crops"], correct: 0, explanation:"Protected cultivation in Telangana is promoted for high-value crops that benefit from climate control: capsicum, cherry tomato, gerbera, carnation, and vegetable seedling nurseries. Subsidy is available under NHM for polyhouse construction." },
  { id:"aeo17_092", year:2017, subject:"horticulture", question:"'Telangana State Horticulture Nursery Development' programme focuses on:", options: ["Marketing of vegetables only", "Post-harvest infrastructure only", "Mass production of common seeds", "Producing quality planting material (grafts, budded plants, TC plants) to meet the planting material demand"], correct: 3, explanation:"State Horticulture Nursery programme establishes government and private certified nurseries to produce quality planting material (grafted mango, budded citrus, TC banana, rooted cuttings of guava, grape) to meet farmers' demand at affordable prices." },
  { id:"aeo17_093", year:2017, subject:"horticulture", question:"Which is the correct arrangement of mango varieties in order of their harvest season (earliest to latest)?", options: ["Alphonso → Totapuri → Banganapalle → Neelam", "Banganapalle → Dasheri → Neelam → Alphonso", "Banganapalle → Alphonso → Neelam → Dasheri", "Totapuri → Banganapalle → Neelam → Alphonso"], correct: 0, explanation:"Harvest season (approximate): Alphonso (Hapus) — March/April (earliest South India), Totapuri/Banganapalle — April/May, Dashehari (North India) — June/July, Neelam — June/July (latest in South India). In Telangana context: Alphonso earliest, Neelam latest." },
  { id:"aeo17_094", year:2017, subject:"horticulture", question:"'Pit planting' method in mango orchards: pit size recommended is:", options: ["1×1×1 m", "1.5×1.5×1.5 m", "30×30×30 cm", "60×60×60 cm"], correct: 3, explanation:"Standard pit size for mango planting is 60×60×60 cm (1 cubic foot). The pit is filled with a mixture of FYM (25 kg), SSP (500g), and Aldrin/Chlorpyrifos (white ant protection) 15–30 days before planting to allow settling." },
  { id:"aeo17_095", year:2017, subject:"horticulture", question:"National Horticulture Research and Development Foundation (NHRDF) is headquartered at:", options: ["Bengaluru", "Hyderabad", "Nasik (Nashik), Maharashtra", "Ludhiana"], correct: 2, explanation:"NHRDF (National Horticulture Research and Development Foundation), established 1977, is headquartered at Nashik, Maharashtra. It conducts research on onion, garlic, vegetables, and provides technical support to vegetable growers across India." },

  // Government Schemes & General Agriculture (5 Qs)
  { id:"aeo17_096", year:2017, subject:"general-agriculture", question:"'Pradhan Mantri Krishi Sinchai Yojana' (PMKSY) aims at:", options: ["Only drip irrigation promotion", "Agricultural credit guarantee", "Rural employment guarantee", "Har Khet Ko Pani (irrigation to every farm) + More Crop Per Drop (water use efficiency)"], correct: 3, explanation:"PMKSY (launched 2015) has two complementary objectives: 'Har Khet Ko Pani' — ensuring irrigation access to all farmland; and 'More Crop Per Drop' — improving WUE through micro-irrigation (drip, sprinkler), watershed development, and water conservation." },
  { id:"aeo17_097", year:2017, subject:"general-agriculture", question:"'National Livestock Mission' (NLM) promotes:", options: ["Entrepreneurship development in animal husbandry, poultry, fodder production, and breed improvement", "Only dairy development", "Import of exotic cattle breeds", "Cotton-based textile industry"], correct: 0, explanation:"NLM promotes entrepreneurship in animal husbandry sector — processing units, feed/fodder businesses, breed improvement, and risk management for livestock farmers. It covers all species: cattle, buffalo, sheep, goat, pig, and poultry." },
  { id:"aeo17_098", year:2017, subject:"general-agriculture", question:"'Integrated Scheme for Agricultural Marketing' (ISAM) supports:", options: ["Farm mechanisation only", "Only seed distribution", "Only MSP procurement", "Agricultural warehousing infrastructure, cold chains, market intelligence, and e-NAM integration"], correct: 3, explanation:"ISAM (earlier separate schemes merged in 2014) supports: rural primary warehouses/silos, cold storage infrastructure (NCCD), Agmark grading laboratories, market intelligence and news dissemination (AGMARKNET), and e-NAM integration." },
  { id:"aeo17_099", year:2017, subject:"general-agriculture", question:"India's rank in world oilseed production is approximately:", options: ["Second", "First", "Third", "Fourth"], correct: 0, explanation:"India is the second-largest oilseed producing country in the world (after China), producing approximately 35–40 million tonnes of oilseeds annually. Major oilseeds: groundnut, rapeseed-mustard, soybean, sunflower, sesame, linseed, safflower." },
  { id:"aeo17_100", year:2017, subject:"general-agriculture", question:"'Dryland farming' in Telangana covers approximately what percentage of net sown area?", options: ["60%", "80%", "40%", "20%"], correct: 0, explanation:"Approximately 60–65% of Telangana's net sown area (about 75 lakh ha of total 140 lakh ha) is under dryland farming (rainfed, non-irrigated). The remaining 35–40% has some form of irrigation (surface or groundwater)." },

  // ── ADDITIONAL GENERAL STUDIES (15 Qs) ──
  { id:"aeo17_101", year:2017, subject:"general-studies", question:"'Telangana State Road Transport Corporation' (TSRTC) headquarters is located at:", options: ["LB Nagar crop", "Musheerabad, Hyderabad", "Secunderabad type", "Begumpet only"], correct: 1, explanation:"TSRTC headquarters is at Musheerabad, Hyderabad. TSRTC was formed after bifurcation from APSRTC in June 2014." },
  { id:"aeo17_102", year:2017, subject:"general-studies", question:"The first Chief Minister of Telangana State was:", options: ["T. Harish Rao", "Eatala Rajender", "Mahmood Ali", "K. Chandrashekar Rao"], correct: 3, explanation:"K. Chandrashekar Rao (KCR) became the first Chief Minister of Telangana on 2 June 2014 when the state was officially formed after leading the decade-long Telangana statehood movement through TRS party." },
  { id:"aeo17_103", year:2017, subject:"general-studies", question:"Hyderabad is sometimes called 'City of Pearls' because:", options: ["It produces pearls from local rivers", "It was historically a major trading centre for natural pearls and is known for its pearl jewellery industry", "Its soil contains pearl minerals", "It is located on the coast"], correct: 1, explanation:"Hyderabad earned the title 'City of Pearls' due to its historical role as a major natural pearl trading centre during Nizam's era and its still-flourishing pearl jewellery industry concentrated around Charminar." },
  { id:"aeo17_104", year:2017, subject:"general-studies", question:"'Atal Pension Yojana' (APY) is primarily aimed at:", options: ["Only BPL families", "Unorganised sector workers aged 18", "Government employees", "Senior citizens above 60 years"], correct: 1, explanation:"APY (launched June 2015) provides guaranteed pension of ₹1,000–5,000/month at age 60 to unorganised sector workers aged 18–40. Government co-contributes 50% or ₹1,000/year for non-income tax payers." },
  { id:"aeo17_105", year:2017, subject:"general-studies", question:"'Mudra Yojana' (PMMY) provides loans for:", options: ["Student education", "Housing construction", "Agricultural land purchase", "Small and micro business enterprises up to ₹10 lakh without collateral"], correct: 3, explanation:"PMMY (April 2015) provides loans up to ₹10 lakh to small/micro non-farm enterprises without collateral: Shishu (<₹50K), Kishore (₹50K–5L), Tarun (₹5L–10L)." },
  { id:"aeo17_106", year:2017, subject:"general-studies", question:"Which district in Telangana is known as the 'Granite City'?", options: ["Nalgonda", "Karimnagar", "Mahabubnagar", "Nizamabad"], correct: 2, explanation:"Mahabubnagar (and its split districts) is known as the 'Granite City' due to vast granite deposits and a large number of quarrying and processing units for domestic and export markets." },
  { id:"aeo17_107", year:2017, subject:"general-studies", question:"'UIDAI' (Unique Identification Authority of India) is under which ministry?", options: ["Ministry of Law and Justice", "Ministry of Electronics and Information Technology", "Ministry of Finance", "Ministry of Home Affairs"], correct: 1, explanation:"UIDAI is a statutory authority under MeitY (Ministry of Electronics and Information Technology). It oversees the Aadhaar biometric identity system established in January 2009." },
  { id:"aeo17_108", year:2017, subject:"general-studies", question:"Telangana's 'Dharani' portal is related to:", options: ["Integrated land records management and property registration", "Agricultural crop reporting", "Farmer welfare schemes", "Water resources management"], correct: 0, explanation:"Dharani is Telangana's integrated land records and property registration portal (launched November 2020). It integrates pahani records, registration, and mutation in a single transparent platform." },
  { id:"aeo17_109", year:2017, subject:"general-studies", question:"'Goods and Services Tax' (GST) was implemented in India from:", options: ["26 January 2017", "1 July 2017", "1 April 2017", "1 January 2018"], correct: 1, explanation:"GST — India's comprehensive indirect tax reform — was implemented from 1 July 2017, replacing multiple central and state taxes with a unified tax system under the slogan 'One Nation One Tax'." },
  { id:"aeo17_110", year:2017, subject:"general-studies", question:"ISRO successfully launched 104 satellites in a single rocket mission (PSLV-C37) in:", options: ["2015", "2016", "2017", "2018"], correct: 2, explanation:"On 15 February 2017, ISRO launched 104 satellites simultaneously using PSLV-C37 in a single mission, setting a world record. This included India's Cartosat-2D and 101 international nano-satellites." },
  { id:"aeo17_111", year:2017, subject:"general-studies", question:"Panchayat Raj system in Telangana consists of how many tiers?", options: ["Two tiers", "Single tier", "Three tiers", "Four tiers"], correct: 2, explanation:"Telangana's Panchayati Raj has three tiers: Gram Panchayat (village), Mandal Parishad (mandal), and Zilla Parishad (district), established under the 73rd Constitutional Amendment." },
  { id:"aeo17_112", year:2017, subject:"general-studies", question:"'Rythu Bandhu' investment support is given per:", options: ["Per farmer regardless of land holding", "Per acre of agricultural land owned", "Per crop per season only", "Per annum as lump sum regardless of crops"], correct: 1, explanation:"Rythu Bandhu provides ₹10,000 per acre per year (₹5,000 per season for kharif and rabi) to all farmers owning agricultural land in Telangana. It is land-area based, not farmer-number based." },
  { id:"aeo17_113", year:2017, subject:"general-studies", question:"The Godavari river originates from:", options: ["Eastern Ghats", "Himalayas", "Western Ghats, Maharashtra", "Deccan Plateau, Telangana"], correct: 2, explanation:"Godavari originates from Trimbakeshwar near Nashik, Maharashtra at 1,067m elevation. India's second-longest river, it is called 'Dakshina Ganga' and is vital for Telangana's irrigation." },
  { id:"aeo17_114", year:2017, subject:"general-studies", question:"'Haritha Haram' programme in Telangana aims to increase tree cover to:", options: ["50%", "24%", "40%", "33%"], correct: 0, explanation:"Haritha Haram (Green Garland, launched 2015) aims to increase Telangana's tree cover from 24% to 33% initially and ultimately to 50% through plantation of 230 crore saplings in 5 years." },
  { id:"aeo17_115", year:2017, subject:"general-studies", question:"Telangana state flower is:", options: ["Lotus", "Rose", "Tangedu", "Jasmine"], correct: 2, explanation:"Tangedu (Senna auriculata) is Telangana's state flower. Its yellow flowers are used in the traditional Bathukamma festival floral arrangement and bloom abundantly during the festive season." },

  // ── ADDITIONAL AGRICULTURE QUESTIONS (35 Qs) ──
  { id:"aeo17_116", year:2017, subject:"agronomy", question:"The 'Harvest Index' (HI) of modern HYV wheat is approximately:", options: ["25–30%", "15–20%", "60–70%", "40–50%"], correct: 3, explanation:"Harvest Index = Economic yield/Biological yield × 100. Modern HYV wheat has HI of 40–50% (improved from traditional 25–30%), meaning 40–50% of total dry matter goes into grain, reflecting breeding efficiency." },
  { id:"aeo17_117", year:2017, subject:"agronomy", question:"'Biofertilizer' Azospirillum is recommended for:", options: ["Leguminous crops only", "Only horticultural crops", "Non", "Only oilseeds"], correct: 2, explanation:"Azospirillum is an associative nitrogen-fixer colonising rhizosphere of non-leguminous cereals (maize, sorghum, wheat, rice, sugarcane), fixing 20–40 kg N/ha. Also produces plant growth-promoting substances." },
  { id:"aeo17_118", year:2017, subject:"agronomy", question:"'Seed priming' improves crop stand establishment by:", options: ["Controlled pre", "Heat treatment of seeds", "Treating seeds with fungicide only", "Storing seeds for long duration"], correct: 0, explanation:"Seed priming involves controlled hydration to allow pre-germination metabolism without radical protrusion. After priming and re-drying, seeds germinate faster and more uniformly, improving field establishment especially under stress conditions." },
  { id:"aeo17_119", year:2017, subject:"agronomy", question:"The crop producing the highest dry matter per hectare per day is:", options: ["Rice crop", "Sugarcane", "Wheat species", "Maize type"], correct: 1, explanation:"Sugarcane has the highest net primary productivity (50–80 t dry matter/ha/year = 140–220 kg/ha/day) due to C4 photosynthesis, long growing season, and high leaf area index." },
  { id:"aeo17_120", year:2017, subject:"agronomy", subject:"agronomy", question:"'Pulses Mission' in Telangana targets area expansion under:", options: ["Soybean only", "Groundnut only", "Redgram, bengal gram, green gram, and black gram", "Only black gram"], correct: 2, explanation:"Telangana Pulses Mission promotes all four major pulses: redgram (kharif, 5–6 lakh ha), bengal gram (rabi chickpea), green gram (moong), and black gram (urad) through HYV seed support and demonstration." },
  { id:"aeo17_121", year:2017, subject:"agronomy", question:"'Minimum tillage' is practiced primarily to:", options: ["Increase fuel and labour costs", "Eliminate weed management", "Conserve soil moisture, reduce erosion, lower input costs, and maintain soil health", "Increase crop density"], correct: 2, explanation:"Conservation/minimum tillage reduces soil disturbance, conserving moisture, minimising erosion, maintaining soil organic matter, reducing fuel and labour costs by 25–40%, and supporting earthworm populations." },
  { id:"aeo17_122", year:2017, subject:"soil-science", question:"'Slow-release fertilizers' improve efficiency by:", options: ["Synchronising nutrient release with crop demand, reducing losses", "Being cheaper than regular fertilizers", "Providing nutrients faster", "Eliminating the need for split application"], correct: 0, explanation:"Slow-release/controlled-release fertilizers (neem-coated urea, polymer-coated urea) match nutrient supply with crop uptake, reducing volatilisation, leaching, and denitrification losses while improving NUE by 15–25%." },
  { id:"aeo17_123", year:2017, subject:"soil-science", question:"'Soil texture triangle' classifies soil based on percentages of:", options: ["Sand, silt, and clay", "Colour and structure", "Organic matter content", "pH and EC"], correct: 0, explanation:"USDA Soil Texture Triangle classifies soils into textural classes (clay, silt loam, sandy loam, etc.) based on percentages of sand (0.05–2mm), silt (0.002–0.05mm), and clay (<0.002mm)." },
  { id:"aeo17_124", year:2017, subject:"soil-science", question:"'Neem cake' applied to soil acts as:", options: ["Only as a nitrogen source", "Only as a fungicide", "Only as a potassium source", "N source + nitrification inhibitor + nematicide — controls root nematodes"], correct: 3, explanation:"Neem cake is multipurpose: N source (3%), nitrification inhibitor (nimbidin slows NH4→NO3 conversion), and nematicide (kills root-knot nematodes). Applied at 250–500 kg/ha it reduces N losses and pest damage." },
  { id:"aeo17_125", year:2017, subject:"soil-science", question:"'Pyrite' (FeS₂) application to soil is used for:", options: ["Providing phosphorus", "Adding potassium", "Increasing soil pH", "Reclaiming alkaline soils by producing H₂SO₄ on oxidation"], correct: 3, explanation:"Pyrite oxidises in soil to form H₂SO₄ which reacts with CaCO₃ releasing Ca²⁺ and lowering pH in alkaline/sodic soils. Application rate: 2–8 t/ha depending on soil pH and ESP." },
  { id:"aeo17_126", year:2017, subject:"entomology", question:"'Diamond Back Moth' (Plutella xylostella) is a serious pest of:", options: ["Tomato", "Cruciferous vegetables (cabbage, cauliflower, mustard)", "Cotton", "Paddy"], correct: 1, explanation:"DBM is the most destructive pest of cruciferous crops globally. Larvae mine leaves leaving 'windowpanes'. It has developed resistance to almost all insecticide classes." },
  { id:"aeo17_127", year:2017, subject:"plant-pathology", question:"'Early blight' of potato and tomato is caused by:", options: ["Alternaria solani", "Pythium ultimum", "Phytophthora infestans", "Fusarium solani"], correct: 0, explanation:"Early blight of potato and tomato is caused by Alternaria solani, showing target-board concentric ring lesions on older leaves. Distinguished from late blight (Phytophthora) by symptom pattern and disease conditions." },
  { id:"aeo17_128", year:2017, subject:"entomology", question:"'Yellow sticky traps' monitor which pests in vegetable crops?", options: ["Cutworms", "Root grubs", "Whiteflies, aphids, and leaf miners attracted to yellow colour", "Stem borers"], correct: 2, explanation:"Yellow sticky traps (yellow cards with sticky coating) monitor whiteflies, aphids, leaf miners, and thrips — all attracted to yellow. Trap counts guide ETL-based spray decisions." },
  { id:"aeo17_129", year:2017, subject:"plant-pathology", question:"'Late blight' of potato outbreak requires:", options: ["Alkaline soil conditions", "Hot dry conditions", "Cool humid weather", "Flooded field conditions"], correct: 2, explanation:"Late blight (Phytophthora infestans) epidemics require: temperature 15–18°C, RH >90%, leaf wetness >10–12 hours. The 'Beaumont period' predicts outbreaks. Disease forecasting models are used for spray timing." },
  { id:"aeo17_130", year:2017, subject:"entomology", question:"'Biological control' using NPV (Nuclear Polyhedrosis Virus) is effective against:", options: ["Lepidopteran larvae (caterpillars) — highly specific", "Soil insects", "Aphids and whiteflies", "All insect pests equally"], correct: 0, explanation:"NPV baculoviruses are highly host-specific — HaNPV targets only Helicoverpa armigera larvae, SpltNPV targets Spodoptera litura. Used at 250 LE/ha, they are safe alternatives to chemical insecticides." },
  { id:"aeo17_131", year:2017, subject:"horticulture", question:"'Turmeric' is cultivated for its:", options: ["Underground rhizomes rich in curcumin", "Leaves only", "Fruits", "Seeds"], correct: 0, explanation:"Turmeric rhizomes contain curcumin (yellow pigment, anti-inflammatory). India produces 80% of world's turmeric. Nizamabad (Telangana) produces the famous 'Nizamabad Bulb' variety with high curcumin content." },
  { id:"aeo17_132", year:2017, subject:"horticulture", question:"'Crop scheduling' in vegetable production means:", options: ["Growing one variety throughout the year", "Avoiding crop rotation", "Only growing seasonal vegetables", "Sowing at regular 2"], correct: 3, explanation:"Succession sowing (crop scheduling) staggers harvest over the season by sowing at regular intervals, ensuring continuous supply to market and avoiding price crashes at peak harvest." },
  { id:"aeo17_133", year:2017, subject:"horticulture", question:"'IIHR' (Indian Institute of Horticultural Research) is located at:", options: ["Hessarghatta, Bengaluru", "Pune crop", "Hyderabad variety", "Nashik crop"], correct: 0, explanation:"ICAR-IIHR is at Hessarghatta, Bengaluru, Karnataka. It developed important varieties including Arka Abhay (YMV-resistant okra), Arka Meghali, and many vegetable and fruit crop varieties." },
  { id:"aeo17_134", year:2017, subject:"horticulture", question:"'Controlled atmosphere (CA) storage' for apples maintains:", options: ["Reduced O₂ (1", "Increased O₂ and CO₂", "Added chemical preservatives", "Frozen fruit condition"], correct: 0, explanation:"CA storage greatly reduces respiration and ethylene production, extending apple shelf life from 1–2 months (refrigerated) to 8–12 months. Precise gas composition differs by variety." },
  { id:"aeo17_135", year:2017, subject:"horticulture", question:"'Chilling requirement' for flowering is needed by:", options: ["Temperate fruits like apple, pear, and cherry", "Vegetables like tomato", "Tropical fruits like mango and banana", "Leafy vegetables"], correct: 0, explanation:"Temperate fruits require specific hours of temperatures below 7.2°C (chilling units) to break dormancy. Insufficient chilling causes delayed, erratic flowering and poor fruit set in apple, pear, peach, cherry." },
  { id:"aeo17_136", year:2017, subject:"extension", question:"'ICT in Agriculture' refers to use of:", options: ["Mobile apps, internet, radio, TV, SMS for agricultural information dissemination", "International Commercial Transactions", "Integrated Crop Technology", "Industrial and Chemical Technologies"], correct: 0, explanation:"ICT (Information and Communication Technologies) in agriculture includes mobile phones (SMS, apps, IVR), internet portals (e-NAM, Kisan Suvidha), radio farm broadcasts, Kisan TV channel, and social media for timely farmer advisory." },
  { id:"aeo17_137", year:2017, subject:"extension", question:"'Zero Budget Natural Farming' eliminates the need for:", options: ["Crop rotation", "Solar energy", "Purchased external chemical inputs — based on local bioinputs (Jivamrita, Bijamrita, Mulch, Waaphasa)", "Rainfall"], correct: 2, explanation:"ZBNF uses local bioinputs: Jivamrita (fermented cow dung + urine spray), Bijamrita (seed treatment), mulching, and Waaphasa (soil aeration). Eliminating purchased inputs means near-zero external costs." },
  { id:"aeo17_138", year:2017, subject:"extension", question:"'FPO' (Farmer Producer Organisation) under Companies Act gives farmers:", options: ["Government employment", "Legal collective entity", "Free land distribution", "Loan waivers"], correct: 1, explanation:"FPO registration gives farmers: legal company status, limited liability, collective input procurement (10–30% cost saving), processing capability, and stronger market negotiating position." },
  { id:"aeo17_139", year:2017, subject:"general-agriculture", question:"'National Mission on Oilseeds and Oil Palm' (NMOOP) in Telangana promotes:", options: ["Cotton area expansion", "Oil palm cultivation in Khammam, Nalgonda and Bhadradri-Kothagudem districts", "Sugarcane expansion", "Rice production"], correct: 1, explanation:"NMOOP promotes oil palm cultivation (very high oil yield: 3.5–4 t/ha, regular monthly income) in high-rainfall districts of Telangana. TSIPL and state agencies provide planting material and buy-back guarantees." },
  { id:"aeo17_140", year:2017, subject:"general-agriculture", question:"'Soil health' is broadly defined as:", options: ["Capacity to produce maximum yield always", "Ability to hold maximum water", "Resistance to all types of erosion", "Capacity of soil to function as a living ecosystem sustaining plants, animals, and humans"], correct: 3, explanation:"Soil health encompasses physical (structure, texture), chemical (nutrients, pH), and biological (microbial life) properties that enable soil to function as a vital ecosystem for plant growth and environmental services." },
  { id:"aeo17_141", year:2017, subject:"agronomy", question:"'Crop rotation' helps break pest and disease cycles by:", options: ["Using more pesticides each year", "Alternating host and non", "Applying more fertilizers", "Irrigating more frequently"], correct: 1, explanation:"Crop rotation disrupts pest and disease cycles: pathogens and insects that are host-specific decline when non-host crops are grown in the same field in the next season, reducing inoculum and pest populations naturally." },
  { id:"aeo17_142", year:2017, subject:"soil-science", question:"'Organic carbon' percentage in soil determines:", options: ["Soil pH only", "Soil texture only", "Soil colour only", "Soil fertility, water retention, structure, and biological activity — indicator of overall soil health"], correct: 3, explanation:"Soil Organic Carbon (SOC) is the master indicator of soil health: higher SOC means better nutrient supply, water retention, aggregate stability, CEC, microbial biomass, and buffering capacity. Target: >0.5% for dryland, >0.8% for irrigated soils." },
  { id:"aeo17_143", year:2017, subject:"plant-pathology", question:"'Biocontrol' agent Trichoderma harzianum is effective against:", options: ["Sucking pests", "Viral diseases", "Soil", "Bacterial diseases"], correct: 2, explanation:"T. harzianum/viride is an antagonistic fungus used for seed and soil treatment against soil-borne pathogens. It produces antibiotics (trichodermin, harzianum A), mycoparasitises pathogens, and competes for space and nutrients." },
  { id:"aeo17_144", year:2017, subject:"horticulture", question:"'Pre-harvest drop' of mango is managed by spraying:", options: ["NAA (Naphthalene Acetic Acid) at 20–40 ppm", "Urea", "Copper sulphate", "Fungicide"], correct: 0, explanation:"Pre-harvest mango fruit drop is managed by 2 sprays of NAA at 20–40 ppm — first at marble stage, second at ripening initiation. NAA inhibits formation of the abscission layer preventing premature drop." },
  { id:"aeo17_145", year:2017, subject:"extension", question:"'Kisan TV' (Doordarshan Kisan channel) provides:", options: ["Only rural entertainment", "Government political broadcasts", "24-hour agricultural information, farm tips, weather advisory, scheme information, and market prices for farmers", "Entertainment only"], correct: 2, explanation:"DD Kisan (launched 2015) is India's first 24-hour dedicated agricultural TV channel providing: crop advisory, weather updates, market prices, scheme information, success stories of progressive farmers, and research updates." },
  { id:"aeo17_146", year:2017, subject:"general-agriculture", question:"'Mission Kakatiya' Phase-wise restoration target in Telangana is:", options: ["46,531 tanks across all districts", "5,000 tanks", "Only major irrigation tanks", "100 tanks"], correct: 0, explanation:"Mission Kakatiya aims to restore all 46,531 minor irrigation tanks in Telangana (Phase I: 2015–16 to Phase V), rejuvenating approximately 9.78 lakh acres of ayacut and recharging groundwater." },
  { id:"aeo17_147", year:2017, subject:"agronomy", question:"'PMFBY' crop insurance covers losses due to:", options: ["Non", "Only drought", "Only flood", "All risks including farmer negligence"], correct: 0, explanation:"PMFBY covers all non-preventable natural risks including drought (area-yield basis), flood, hailstorm, cyclone, lightning, pest and disease epidemics, and post-harvest losses for 14 days in field." },
  { id:"aeo17_148", year:2017, subject:"soil-science", question:"'Foliar nutrition' is practiced when:", options: ["Only for organic farming", "Only for micronutrients always", "Soil application is inefficient (alkaline soils for Fe, Zn) or rapid correction is needed in standing crops", "Soil is fertile"], correct: 2, explanation:"Foliar sprays are used when: soil conditions prevent absorption (Fe, Zn unavailable in alkaline soils), rapid correction needed for standing crops, or during drought when root absorption is limited." },
  { id:"aeo17_149", year:2017, subject:"plant-pathology", question:"'APEDA' (Agricultural and Processed Food Products Export Development Authority) was established to:", options: ["Regulate domestic agricultural markets", "Promote export of scheduled agricultural and processed food products from India", "Control food prices domestically", "Import agricultural products"], correct: 1, explanation:"APEDA (1986, Ministry of Commerce) promotes and develops export of fruits, vegetables, meat, processed foods, cereals, and non-traditional products. It sets quality standards and provides financial assistance for export infrastructure." },
  { id:"aeo17_150", year:2017, subject:"general-agriculture", question:"'Carbon sequestration' through Zero Tillage agriculture means:", options: ["Burning crop residues releasing CO₂", "Applying more chemical fertilizers", "Storing atmospheric CO₂ as soil organic carbon by reducing soil disturbance and adding organic matter", "Converting agricultural land to industry"], correct: 2, explanation:"Agricultural carbon sequestration (zero-till, cover crops, organic amendments) stores atmospheric CO₂ as SOC. Each 1% increase in SOC sequesters ~15 t CO₂/ha, contributing to climate change mitigation while improving soil fertility." },
] as PYQQuestion[];
